css:
.print-format p { margin: 0 0 2px; line-height: 1.35; }
.print-format .row.section-break { margin-bottom: 4px; }
.print-format .table { margin-bottom: 6px; }
.print-format .afm-items th, .print-format .afm-items td { vertical-align: middle; padding: 3px 4px !important; }
.print-format .afm-items tr > :nth-child(1) { text-align: center !important; }
.print-format .afm-items tr > :nth-child(2), .print-format .afm-items tr > :nth-child(3) { text-align: left !important; }
.print-format .afm-items tr > :nth-child(n+4) { text-align: right !important; white-space: nowrap; }
.print-format .afm-items tr:last-child > td { text-align: right !important; font-weight: bold; }
.print-format .afm-items tr:last-child > td:first-child { text-align: center !important; }

